module fixed_point_adder #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

wire [N-1:0] abs_a;
wire [N-1:0] abs_b;
wire [N-1:0] diff;
wire [N-1:0] temp_res;
assign abs_a = (a[N-1]) ? (~a + 1) : a;
assign abs_b = (b[N-1]) ? (~b + 1) : b;

wire sign_same = (a[N-1] == b[N-1]);

assign temp_res = (sign_same) ? (abs_a + abs_b) : ((a > b) ? (abs_a - abs_b) : (abs_b - abs_a));

assign c = (temp_res != 0 && !sign_same) ? {~(a > b), temp_res} : {a[N-1], temp_res};
endmodule
